// @ts-check
// Regenerated by ../tools/regenerate-canonical-vectors.mjs without importing this module.

import test, { describe } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import {
  CHAIN_KEY_CONSTRUCTION_ID,
  CHAIN_KEY_CONSTRUCTION,
  CHAIN_KEY_BYTES,
  CHAIN_KEY_PROFILE,
  chainKeyConstructionProfile,
  chainKeyCoordinatePrimitive,
  chainKeyDerivations,
  chainKeyLabelPrimitive,
  chainKeyLabelAt,
  chainKeyLeafPrimitive,
  chainKeyRootPrimitive,
  chainKeyStepPrimitive,
  settleChainGeometry,
} from "../core-shared/chainKeyConstruction.js";
import { base64urlDecode, base64urlEncode } from "../../../core-shared/codec.js";

const VECTORS = JSON.parse(
  readFileSync(new URL("./fixtures/dca-profile-chain-keys.vectors.json", import.meta.url), "utf8"),
);
assert.equal(VECTORS.setIdentity, CHAIN_KEY_PROFILE);
assert.equal(VECTORS.status, "canonical-16");
assert.deepEqual(VECTORS.semanticWidths, {
  chainKey: 16,
  contentKey: 16,
  keyDerivationSecret: 32,
  periodKey: 16,
  periodKeyWrapAlgorithm: "AES-128-GCM",
});

/** @param {string} hex */
function bytes(hex) {
  return Uint8Array.from(hex.match(/../g) ?? [], (pair) => Number.parseInt(pair, 16));
}
/** @param {any} vector */
function geometryOf(vector) {
  return settleChainGeometry({
    chainsPerDay: vector.chainsPerDay,
    periodMinutes: vector.periodMinutes,
  });
}
/** @param {any} vector */
function terminalLabelOf(vector) {
  return chainKeyLabelAt(vector.windowStart + (vector.N - 1) * vector.periodMinutes);
}
const canonical = chainKeyDerivations(CHAIN_KEY_CONSTRUCTION);

describe("The canonical dca-construction-chain-keys construction", () => {
  test("exports the five one-call primitives the neutral bridge observes", async () => {
    const vector = VECTORS.cases[0];
    const geometry = { chainsPerDay: vector.chainsPerDay, periodMinutes: vector.periodMinutes };
    const terminal = await chainKeyRootPrimitive({
      keyDerivationSecret: bytes(vector.secretHex),
      accessGroup: vector.accessGroup,
      ...geometry,
      windowStart: vector.windowStart,
    });
    assert.deepEqual(chainKeyCoordinatePrimitive({ t: vector.label, ...geometry }), {
      windowStart: vector.windowStart,
      position: vector.position,
    });
    assert.equal(
      chainKeyLabelPrimitive({
        ...geometry,
        windowStart: vector.windowStart,
        position: vector.position,
      }),
      vector.label,
    );
    assert.equal(base64urlEncode(terminal), vector.rootChainKey, "Root is one terminal derivation");
    const stepped = await chainKeyStepPrimitive({
      chainKey: terminal,
      accessGroup: vector.accessGroup,
      ...geometry,
      windowStart: vector.windowStart,
      position: vector.N - 2,
    });
    assert.equal(
      base64urlEncode(stepped),
      vector.chainKeyAfterOneStep,
      "Step binds exactly terminal - 1",
    );
    const chainKeyAtLabel = await canonical.chainKeyFromChainKey({
      chainKey: terminal,
      accessGroup: vector.accessGroup,
      suppliedT: terminalLabelOf(vector),
      targetT: vector.label,
      geometry: geometryOf(vector),
    });
    const periodKey = await chainKeyLeafPrimitive({
      chainKey: chainKeyAtLabel,
      accessGroup: vector.accessGroup,
      ...geometry,
      windowStart: vector.windowStart,
      position: vector.position,
    });
    assert.equal(
      base64urlEncode(periodKey),
      vector.periodKey,
      "Leaf binds one supplied chain key at its position",
    );
    await assert.rejects(
      chainKeyStepPrimitive({
        chainKey: terminal,
        accessGroup: vector.accessGroup,
        ...geometry,
        windowStart: vector.windowStart,
        position: vector.N - 1,
      }),
      /one chain-key Step/,
    );
  });

  test("direct Label, Root, Step and Leaf reject a windowStart that is not on their geometry grid", async () => {
    const vector = VECTORS.cases[0];
    const geometry = { chainsPerDay: vector.chainsPerDay, periodMinutes: vector.periodMinutes };
    const misalignedWindowStart = vector.windowStart + 1;
    const terminal = await chainKeyRootPrimitive({
      keyDerivationSecret: bytes(vector.secretHex),
      accessGroup: vector.accessGroup,
      ...geometry,
      windowStart: vector.windowStart,
    });
    assert.throws(
      () =>
        chainKeyLabelPrimitive({
          ...geometry,
          windowStart: misalignedWindowStart,
          position: vector.position,
        }),
      /off the 15-minute family grid/,
    );
    await assert.rejects(
      chainKeyRootPrimitive({
        keyDerivationSecret: bytes(vector.secretHex),
        accessGroup: vector.accessGroup,
        ...geometry,
        windowStart: misalignedWindowStart,
      }),
      /off the 15-minute family grid/,
    );
    await assert.rejects(
      chainKeyStepPrimitive({
        chainKey: terminal,
        accessGroup: vector.accessGroup,
        ...geometry,
        windowStart: misalignedWindowStart,
        position: vector.N - 2,
      }),
      /off the 15-minute family grid/,
    );
    await assert.rejects(
      chainKeyLeafPrimitive({
        chainKey: terminal,
        accessGroup: vector.accessGroup,
        ...geometry,
        windowStart: misalignedWindowStart,
        position: vector.position,
      }),
      /off the 15-minute family grid/,
    );
  });

  test("has the one fixed 16-byte chain-key construction", () => {
    const profile = chainKeyConstructionProfile(CHAIN_KEY_CONSTRUCTION);
    assert.equal(profile.name, "dca-construction-chain-keys");
    assert.equal(profile.constructionId, "dca-construction-chain-keys");
    assert.equal(profile.constructionId, CHAIN_KEY_CONSTRUCTION_ID);
    assert.equal(profile.chainKeyBytes, CHAIN_KEY_BYTES);
    assert.equal(profile.chainKeyBytes, 16);
  });

  test("the recorded Root, Step and Leaf contexts carry dca-construction-chain-keys", async () => {
    const vector = VECTORS.cases[0];
    const current = new TextEncoder().encode("dca-construction-chain-keys");
    /** @param {Uint8Array} ikm @param {Uint8Array} info */
    const hkdf = async (ikm, info) =>
      new Uint8Array(
        await crypto.subtle.deriveBits(
          { name: "HKDF", hash: "SHA-256", salt: new Uint8Array(0), info },
          await crypto.subtle.importKey("raw", ikm, "HKDF", false, ["deriveBits"]),
          128,
        ),
      );
    const derivations = [
      ["Root", vector.rootInfoHex, bytes(vector.secretHex), vector.rootChainKey],
      [
        "Step",
        vector.stepInfoHex,
        base64urlDecode(vector.rootChainKey),
        vector.chainKeyAfterOneStep,
      ],
      [
        "Leaf",
        vector.leafInfoHex,
        base64urlDecode(vector.cutoffChainKeys[vector.label]),
        vector.periodKey,
      ],
    ];
    for (const [name, infoHex, ikm, expected] of derivations) {
      const info = bytes(infoHex);
      // domain octet, u16 length 27, then the construction identifier
      assert.deepEqual([info[1], info[2]], [0, 27], `${name}: identifier length`);
      assert.deepEqual(info.subarray(3, 3 + current.length), current, `${name}: identifier octets`);
      assert.equal(base64urlEncode(await hkdf(ikm, info)), expected, `${name}: recorded bytes`);
      // Keep every other context byte and the IKM fixed: changing only the
      // construction identifier must separate all three derivations.
      const other = Uint8Array.from(info);
      const invented = Uint8Array.from(current, (byte, index) =>
        index === current.length - 1 ? byte ^ 1 : byte,
      );
      assert.equal(invented.length, current.length);
      other.set(invented, 3);
      assert.deepEqual(other.subarray(3 + current.length), info.subarray(3 + current.length));
      assert.notEqual(
        base64urlEncode(await hkdf(ikm, other)),
        expected,
        `${name}: construction separation`,
      );
    }
  });

  test("derives every regenerated Root, Step, Leaf and expansion", async () => {
    for (const vector of VECTORS.cases) {
      const geometry = geometryOf(vector);
      const terminalT = terminalLabelOf(vector);
      const terminal = await canonical.rootChainKey({
        keyDerivationSecret: bytes(vector.secretHex),
        accessGroup: vector.accessGroup,
        terminalT,
        geometry,
      });
      assert.equal(terminal.length, 16, `${vector.id}: Root width`);
      assert.equal(base64urlEncode(terminal), vector.rootChainKey, `${vector.id}: Root`);
      const expansion = await canonical.periodKeysFromChainKey({
        chainKey: terminal,
        accessGroup: vector.accessGroup,
        suppliedT: terminalT,
        cutoffT: terminalT,
        geometry,
      });
      assert.equal(expansion.length, vector.N, `${vector.id}: expansion length`);
      assert.deepEqual(
        expansion.map((entry) => base64urlEncode(entry.key)),
        vector.expansion,
        `${vector.id}: expansion`,
      );
      const step = await canonical.chainKeyFromChainKey({
        chainKey: terminal,
        accessGroup: vector.accessGroup,
        suppliedT: terminalT,
        targetT: expansion.at(-2).t,
        geometry,
      });
      assert.equal(base64urlEncode(step), vector.chainKeyAfterOneStep, `${vector.id}: Step`);
      const chainKey = await canonical.chainKeyFromChainKey({
        chainKey: terminal,
        accessGroup: vector.accessGroup,
        suppliedT: terminalT,
        targetT: vector.label,
        geometry,
      });
      const periodKey = await canonical.periodKeyFromChainKey({
        chainKey,
        accessGroup: vector.accessGroup,
        t: vector.label,
        geometry,
      });
      assert.equal(base64urlEncode(periodKey), vector.periodKey, `${vector.id}: Leaf`);
    }
  });

  test("records the construction identifier every Root, Step and Leaf context carries", () => {
    assert.match(VECTORS.replacement, /Every Root, Step and Leaf context carries that identifier/);
    assert.equal(VECTORS.semanticWidths.keyDerivationSecret, 32);
  });

  test("refuses 15, 17, 24 and 32-byte supplied chain keys", async () => {
    const vector = VECTORS.cases[0];
    const geometry = geometryOf(vector);
    for (const width of [15, 17, 24, 32]) {
      await assert.rejects(
        canonical.periodKeyFromChainKey({
          chainKey: new Uint8Array(width),
          accessGroup: vector.accessGroup,
          t: vector.label,
          geometry,
        }),
        (error) => error.code === "bad_config" && /exactly 16 bytes/.test(error.message),
      );
    }
  });

  test("keeps the key-derivation secret at exactly 32 bytes", async () => {
    const vector = VECTORS.cases[0];
    for (const width of [15, 16, 17, 24, 31, 33]) {
      await assert.rejects(
        canonical.rootChainKey({
          keyDerivationSecret: new Uint8Array(width),
          accessGroup: vector.accessGroup,
          terminalT: terminalLabelOf(vector),
          geometry: geometryOf(vector),
        }),
        (error) =>
          error.code === "bad_config" &&
          /exactly 32 key-derivation-secret bytes/.test(error.message),
      );
    }
  });

  test("refuses the retired secret member even beside the selected input", async () => {
    const vector = VECTORS.cases[0];
    await assert.rejects(
      canonical.rootChainKey({
        keyDerivationSecret: bytes(vector.secretHex),
        secret: undefined,
        accessGroup: vector.accessGroup,
        terminalT: terminalLabelOf(vector),
        geometry: geometryOf(vector),
      }),
      (error) =>
        error.code === "unsupported_option" &&
        /keyDerivationSecret, not secret/.test(error.message),
    );
  });

  test("refuses unsupported construction names rather than treating width as a selector", () => {
    for (const name of [
      "dca-construction-chain-keys-24",
      "dca-construction-chain-keys-invented",
      "dca-vX-chain-keys",
      "dca-chain-keys",
      "",
      16,
    ]) {
      assert.throws(
        () => chainKeyConstructionProfile(/** @type {any} */ (name)),
        /construction profile/,
      );
      assert.throws(() => chainKeyDerivations(/** @type {any} */ (name)), /construction profile/);
    }
  });
});
